    try:
        R = int(next(iterator))
        C = int(next(iterator))
    except StopIteration:
        return

    grid = []
    for _ in range(R):
        grid.append(next(iterator))

    passengers = []
    seats = []

    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'X':
                passengers.append((r, c))
            elif grid[r][c] == 'L':
                seats.append((r, c))

    explosions = 0

    while passengers and seats:
        # Map each seat to a list of passengers targeting it with the minimum distance
        seat_targets = defaultdict(list)  # seat -> list of passenger indices

        for p_idx, (pr, pc) in enumerate(passengers):
