                seat_groups[seat_idx] = []
            seat_groups[seat_idx].append(p_idx)

        # Process each seat group
        seats_to_remove = set()
        passengers_to_remove = set()

        for seat_idx, p_indices in seat_groups.items():
            if len(p_indices) == 1:
                # Unique closest passenger
                p_idx = p_indices[0]
                passengers_to_remove.add(p_idx)
                seats_to_remove.add(seat_idx)
            else:
                # Collision: multiple passengers equally close to this seat
                # The problem states: "If however they are all equally close, they will all run to the seat resulting in a massive explosion"
                # Since we grouped by the best seat for each passenger, and they all have the same best seat,
