import sys
import math

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        R = int(next(iterator))
        C = int(next(iterator))
    except StopIteration:
        return

    grid = []
    for _ in range(R):
        grid.append(next(iterator))

    passengers = []
    seats = []

    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'X':
                passengers.append((r, c))
            elif grid[r][c] == 'L':
                seats.append((r, c))

    explosions = 0

    while passengers and seats:
        # Calculate distances for all passenger-seat pairs
        # We need to find the global minimum distance among all valid pairs
        min_dist = float('inf')
        for p in passengers:
            for s in seats:
                d = math.sqrt((p[0] - s[0])**2 + (p[1] - s[1])**2)
                if d < min_dist:
                    min_dist = d

        # Now group passengers by the seat they target at this min_dist
        # Key: seat index, Value: list of passenger indices
        seat_targets = {}
        for p_idx, p in enumerate(passengers):
            for s_idx, s in enumerate(seats):
                d = math.sqrt((p[0] - s[0])**2 + (p[1] - s[1])**2)
                if abs(d - min_dist) < 1e-9:
                    if s_idx not in seat_targets:
                        seat_targets[s_idx] = []
                    seat_targets[s_idx].append(p_idx)

        # Process each seat that has at least one passenger at min_dist
        removed_passengers = set()
        removed_seats = set()

        for s_idx, p_indices in seat_targets.items():
            if len(p_indices) == 1:
                # Unique closest passenger, they sit
                removed_passengers.add(p_indices[0])
                removed_seats.add(s_idx)
            else:
                # Collision! Explosion
                explosions += 1
                for p_idx in p_indices:
                    removed_passengers.add(p_idx)
                removed_seats.add(s_idx)

        # Update lists
        passengers = [p for i, p in enumerate(passengers) if i not in removed_passengers]
        seats = [s for i, s in enumerate(seats) if i not in removed_seats]

    print(explosions)

if __name__ == "__main__":
    solve()
